class Solution {
  public int longestSubstring(String s, int k) {
    return solve(s, 0, s.length(), k);
  }

  // any character occurring fewer than k times splits the string; the answer lies within one piece
  private int solve(String s, int lo, int hi, int k) {
    if (hi - lo < k) return 0;
    int[] count = new int[26];
    for (int i = lo; i < hi; i++) count[s.charAt(i) - 'a']++;
    for (int i = lo; i < hi; i++) {
      if (count[s.charAt(i) - 'a'] < k) {
        int j = i + 1;
        while (j < hi && count[s.charAt(j) - 'a'] < k) j++;
        return Math.max(solve(s, lo, i, k), solve(s, j, hi, k));
      }
    }
    return hi - lo;
  }
}
